$istasyon$::jsonb) as x(
    source_card_key text,
    party_name text,
    source_list_amount numeric,
    source_pdf_amount numeric,
    pdf_list_difference numeric,
    balance_side_source text,
    opening_candidate numeric,
    identity_control text,
    period_risk text,
    legacy_json_balance numeric,
    legacy_json_difference numeric,
    pdf_source text,
    list_location text,
    source_reconciliation_status text,
    note text
  )
)
insert into public.istasyon_opening_source_stage(
  source_card_key,party_name,source_list_amount,source_pdf_amount,
  pdf_list_difference,balance_side_source,opening_candidate,
  identity_control,period_risk,legacy_json_balance,legacy_json_difference,
  pdf_source,list_location,source_reconciliation_status,note,
  source_package,row_hash
)
select
  source_card_key,
  party_name,
  source_list_amount,
  source_pdf_amount,
  pdf_list_difference,
  balance_side_source,
  opening_candidate,
  nullif(identity_control,''),
  nullif(period_risk,''),
  legacy_json_balance,
  legacy_json_difference,
  pdf_source,
  list_location,
  source_reconciliation_status,
  note,
  'Istasyon_Acilis_Cari_Defteri_Preflight_20260926.xlsx',
  encode(digest(
    source_card_key||'|'||party_name||'|'||
    source_list_amount::text||'|'||coalesce(source_pdf_amount,0)::text,
    'sha256'
  ),'hex')
from src
on conflict (source_card_key) do update set
  party_name=excluded.party_name,
  source_list_amount=excluded.source_list_amount,
  source_pdf_amount=excluded.source_pdf_amount,
  pdf_list_difference=excluded.pdf_list_difference,
  balance_side_source=excluded.balance_side_source,
  opening_candidate=excluded.opening_candidate,
  identity_control=excluded.identity_control,
  period_risk=excluded.period_risk,
  legacy_json_balance=excluded.legacy_json_balance,
  legacy_json_difference=excluded.legacy_json_difference,
  pdf_source=excluded.pdf_source,
  list_location=excluded.list_location,
  source_reconciliation_status=excluded.source_reconciliation_status,
  note=excluded.note,
  source_package=excluded.source_package,
  row_hash=excluded.row_hash,
  imported_at=now();

do $$
declare
  v_count integer;
  v_total numeric(18,2);
begin
  select count(*),coalesce(sum(source_list_amount),0)
  into v_count,v_total
  from public.istasyon_opening_source_stage;

  if v_count <> 73 then
    raise exception 'ISTASYON_OPENING_SOURCE_COUNT_MISMATCH expected=73 actual=%',v_count;
  end if;

  if abs(v_total-3741583.88) >= 0.005 then
    raise exception 'ISTASYON_OPENING_SOURCE_BALANCE_MISMATCH expected=3741583.88 actual=%',v_total;
  end if;
end $$;

commit;

select * from public.v_istasyon_opening_source_summary;
select match_status,count(*) as adet
from public.v_istasyon_opening_source_match
group by match_status
order by match_status;
